let conversionRoleMap={},conversionSceneMap={},conversionChapterPlans=[],conversionParsedSource=null,conversionPlanProjectId=null;
function chapterPlansFor(result){return result.groups.map((g,i)=>{const existing=project.scenes.filter(s=>s.name.trim()===g.name?.trim());return conversionChapterPlans[i]||{target:existing.length===1?existing[0].id:'__new__',name:g.name||'序言'}})}
function conversionIssues(result,mode,plans){const errors=[...result.errors];if(result.unresolvedRoles.length)errors.push('请先确认所有未匹配或重名的角色。');if(result.unresolvedTargets.length)errors.push('请先确认所有未匹配或重名的跳转目标。');if(result.hasHeadings){const seenTargets=new Set(),seenNames=new Set();for(const plan of plans){const name=plan.name.trim(),target=mode==='create'?'__new__':plan.target;if(!name)errors.push('章节名称不能为空。');if(seenNames.has(name))errors.push(`多个章节使用名称「${name}」，请区分。`);seenNames.add(name);if(target!=='__new__'){if(!project.scenes.some(s=>s.id===target))errors.push('对应章节已不存在，请重新选择。');if(seenTargets.has(target))errors.push('多个文本章节对应了同一工程章节，请重新选择。');seenTargets.add(target)}}for(const plan of plans){const target=mode==='create'?'__new__':plan.target;if(project.scenes.some(s=>s.name.trim()===plan.name.trim()&&s.id!==target&&!seenTargets.has(s.id)))errors.push(`章节名「${plan.name}」与未更新的章节重复，请调整名称。`)}}return [...new Set(errors)]}
function conversionMappingUI(r){return `${r.roleNames.length?`<section class="conversion-mapping"><h3>角色对应 · ${r.unresolvedRoles.length} 个待确认</h3>${r.roleNames.map((name,i)=>{const issue=r.unresolvedRoles.find(x=>x.name===name),explicit=conversionRoleMap[name]||project.textRoleAliases?.[name],matches=project.characters.filter(c=>c.name.trim()===name.trim()),selected=explicit||(matches.length===1?matches[0].id:'');return `<div class="mapping-row"><div><strong>${esc(name)}</strong><small>${issue?esc(issue.reason):selected==='__narration__'?'已确认保留原文为旁白':explicit?'手动指定的角色对应':'完整名称匹配'}</small></div><select data-role-map="${i}" aria-label="对应角色 ${esc(name)}"><option value="">请选择对应角色</option>${project.characters.map(c=>`<option value="${esc(c.id)}" ${selected===c.id?'selected':''}>${esc(c.name)}${project.characters.filter(x=>x.name===c.name).length>1?' · '+esc(c.description||c.id.slice(0,8)):''}</option>`).join('')}<option value="__narration__" ${selected==='__narration__'?'selected':''}>保留原文为旁白</option></select>${issue?`<button class="btn small" data-action="confirm-new-role" data-id="${i}">确认新建角色</button>`:''}</div>`}).join('')}</section>`:''}${r.unresolvedTargets.length?`<section class="conversion-mapping"><h3>确认跳转目标</h3>${r.unresolvedTargets.map((issue,i)=>`<div class="mapping-row"><div><strong>${esc(issue.name)}</strong><small>${esc(issue.reason)}</small></div><select data-scene-map="${i}" aria-label="对应跳转目标"><option value="">请选择目标章节</option>${project.scenes.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}<option value="__end__">明确结束故事</option></select></div>`).join('')}</section>`:''}`}
previewConversion=function(){
  const source=$('#conversionSource').value;if(project.id!==conversionPlanProjectId){conversionChapterPlans=[];conversionRoleMap={};conversionSceneMap={};conversionQuoteMap={};conversionPlanProjectId=project.id}if(source!==conversionParsedSource){conversionChapterPlans=[];conversionQuoteMap={};conversionParsedSource=source}conversionSource=source;
  const previousMode=$('#conversionMode').value;conversionResult=KotobaCore.parseText(source,project,{roleMap:conversionRoleMap,sceneMap:conversionSceneMap,quoteMap:conversionQuoteMap});const r=conversionResult;conversionChapterPlans=chapterPlansFor(r);
  const modes=r.hasHeadings?[['chapters','按下方对应更新 / 新建章节'],['create','全部作为新章节']]:[['append','追加到当前章节'],['replace','替换当前章节内容']];$('#conversionMode').innerHTML=modes.map(([id,text])=>`<option value="${id}">${text}</option>`).join('');$('#conversionMode').value=modes.some(([id])=>id===previousMode)?previousMode:modes[0][0];$('#conversionMode').disabled=false;
  const errors=conversionIssues(r,$('#conversionMode').value,conversionChapterPlans);$('#conversionCount').textContent=`${r.groups.length} 个章节 · ${r.count} 个剧情块`;$('#applyConversion').disabled=!r.count||!!errors.length;
  $('#conversionPreview').innerHTML=`<p class="field-note">仅按角色表中的唯一完整名称绑定。正文原样保留，不补写台词、不猜测角色。${r.hasHeadings?'可在下方指定更新已有章节，或创建新章节。':''}</p>${conversionMappingUI(r)}${errors.length?`<div class="conversion-warning">${errors.map(esc).join('<br>')}</div>`:''}${r.warnings.length?`<div class="conversion-warning">${r.warnings.map(esc).join('<br>')}</div>`:''}${r.groups.map((g,i)=>{const plan=conversionChapterPlans[i];return `${r.hasHeadings?`<div class="chapter-plan"><label>章节名称<input data-chapter-name="${i}" value="${esc(plan.name)}" maxlength="100"></label><label>写入位置<select data-chapter-target="${i}" ${$('#conversionMode').value==='create'?'disabled':''}><option value="__new__">新建章节</option>${project.scenes.map(s=>`<option value="${esc(s.id)}" ${plan.target===s.id?'selected':''}>更新：${esc(s.name)}</option>`).join('')}</select></label><small>更新会替换该章节的剧情内容，保留场景动画等设置；更改名称会同步重命名。</small></div>`:`<h3 style="font-size:12px;margin:15px 0">${esc(scene().name)}</h3>`}${g.blocks.map(b=>`<div class="conversion-row"><small>${types[b.type]} ${esc(character(b.speaker)?.name||b.sourceSpeaker||'')}</small>${esc(b.text||b.targetName||'')}</div>`).join('')}`}).join('')}`;
};
applyConversion=function(){previewConversion();const r=conversionResult,writeMode=$('#conversionMode').value,plans=conversionChapterPlans.map(p=>({...p}));const errors=conversionIssues(r,writeMode,plans);if(!r.count||errors.length){notify(errors[0]||'没有可转换的剧情');return}
  const writes=r.hasHeadings?r.groups.map((g,i)=>({id:writeMode!=='create'&&plans[i].target!=='__new__'?plans[i].target:uid(),name:plans[i].name.trim(),sourceName:g.name,...(g.multiPortrait!==undefined?{multiPortrait:g.multiPortrait}:{}),blocks:g.blocks,isNew:writeMode==='create'||plans[i].target==='__new__'})):[];
  const apply=()=>{change(()=>{const batchTargets=new Map(writes.filter(w=>w.sourceName).map(w=>[w.sourceName,w.id]));const groups=r.groups;for(const g of groups)for(const b of g.blocks){const links=b.type==='jump'?[b]:b.options||[];for(const link of links){if(!link.targetResolved)link.target=batchTargets.get(link.targetName)||'';delete link.targetName;delete link.targetResolved}delete b.sourceSpeaker}project.textRoleAliases={...project.textRoleAliases,...conversionRoleMap};if(r.hasHeadings){for(const write of writes){if(write.isNew)project.scenes.push({id:write.id,name:write.name,...(write.multiPortrait!==undefined?{multiPortrait:write.multiPortrait}:{}),blocks:write.blocks});else Object.assign(project.scenes.find(s=>s.id===write.id),{name:write.name,...(write.multiPortrait!==undefined?{multiPortrait:write.multiPortrait}:{}),blocks:write.blocks})}sceneId=writes[0].id;selected=writes[0].blocks[0]?.id}else{const blocks=groups.flatMap(g=>g.blocks);if(groups[0]?.multiPortrait!==undefined)scene().multiPortrait=groups[0].multiPortrait;if(writeMode==='replace')scene().blocks=blocks;else scene().blocks.push(...blocks);selected=blocks[0]?.id}playing=false;stopAudio();stageRenderer.reset();view='script';mode='visual'});notify('文本已按确认的角色和章节写入')};
  const updates=writes.filter(w=>!w.isNew);if(updates.length||writeMode==='replace'){dialog('确认更新章节',`<p>${r.hasHeadings?updates.map(w=>{const old=project.scenes.find(s=>s.id===w.id);return `更新「${esc(old.name)}」${old.name!==w.name?' → 「'+esc(w.name)+'」':''}：${old.blocks.length} 个剧情块替换为 ${w.blocks.length} 个。`}).join('<br>'):`替换「${esc(scene().name)}」中的 ${scene().blocks.length} 个剧情块。`}<br>可通过工程撤销恢复本次修改。</p>`,'确认写入',apply)}else apply();
};
document.addEventListener('change',e=>{const d=e.target.dataset;if(d.roleMap!==undefined){const name=conversionResult.roleNames[Number(d.roleMap)];if(name&&e.target.value){conversionRoleMap[name]=e.target.value;previewConversion()}}if(d.sceneMap!==undefined){const issue=conversionResult.unresolvedTargets[Number(d.sceneMap)];if(issue&&e.target.value){conversionSceneMap[issue.name]=e.target.value;previewConversion()}}if(d.chapterName!==undefined){conversionChapterPlans[Number(d.chapterName)].name=e.target.value;previewConversion()}if(d.chapterTarget!==undefined){conversionChapterPlans[Number(d.chapterTarget)].target=e.target.value;previewConversion()}if(e.target.id==='conversionMode')previewConversion()});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action="confirm-new-role"]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();const issue=conversionResult?.unresolvedRoles.find(r=>r.name===conversionResult.roleNames[Number(button.dataset.id)]);if(!issue)return;textDialog('确认创建角色',issue.name,name=>{if(project.characters.some(c=>c.name===name)){notify('已有同名角色，请在对应列表中选择');return}const c={id:uid(),name,color:'#788765',description:'',asset:'',variants:[],defaultVariant:''};change(()=>{project.characters.push(c);conversionRoleMap[issue.name]=c.id});previewConversion()})},true);
